from pathlib import Path
from html import escape
import json
ROOT=Path(__file__).parent
lessons=[]
def add(title,goal,body,questions,hint1,hint2,task,prereq='数组、循环与基本比较'):
 lessons.append(dict(title=title,goal=goal,body=body,questions=questions.split('|'),hints=[hint1,hint2],task=task,prereq=prereq))
def box(t,s):return f'<aside class="callout"><strong>{t}</strong><p>{s}</p></aside>'
def table(head,rows):return '<div class="table-scroll"><table><thead><tr>'+''.join(f'<th>{x}</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def code(s):return '<pre><code>'+escape(s)+'</code></pre>'
add('出发：二分到底在找什么？','分清答案是数值、位置，还是一个分界。',
'''<p class="lead">你要找一本书，不必把每一本都翻开。</p><p>想象书架按编号从小到大摆好：2、5、8、12、16、21、30。要找编号 16，你可以从左向右挨个看，也可以先看中间。看见 12 后，不只知道“这本不是”，还知道左边整排都不可能是 16。</p><p>二分最有用的地方，是一次判断能排除一整段。今天先不写 <code>mid</code>，先说明排除的理由。若书架没有按编号排好，看见 12 就不能断定左边没有 16。</p><h3>给问题起三个名字</h3>'''+table(['问题','真正要交出的东西'],[['16 在不在？','存在性：是 / 否'],['第一本编号不小于 13 的书在哪里？','位置：不是直接输出编号 16'],['最小多大的背包能装下指定物品？','数值：这个数可能根本不在输入中']])+'''<p>本讲统一用从 0 开始的数组下标。位置 0 是第 1 个元素；数量 3 不是下标 3。题面若要求从 1 开始编号，最后再转换。</p>''',
'看见中间的 12，为什么左边可以一起排除？|如果书架变成 16、2、21、12、5、30、8，这个理由还成立吗？|“第一本不小于 13”的答案应该报告位置还是编号？',
'把“左边每本的编号都……”这句话补完整。','二分依赖能够证明的顺序关系；不只是依赖有一个中间位置。',
'画 7 张卡片。分别写出上面三个问题的输入、目标量和答案单位，再把第二问的手推过程讲给家长。')
add('一刀为什么要切在中间？','亲手数出每轮剩余规模，理解对数增长。',
'''<p class="lead">每次只排除一个很慢；每次排除大约一半，范围会很快缩小。</p><p>秘密整数在 1～16。你可以问“它是否不大于 8”。无论回答哪一种，都只剩 8 个候选。继续问中点，候选个数依次变成 16、8、4、2、1。四次是非问题就能定位。</p><p>如果先问“是否不大于 1”，有一种回答会留下 15 个候选。中点的作用是控制最坏情况，而不是保证这次恰好猜中。</p><h3>不用先背 log</h3><p>反过来数：1 翻倍 10 次是 1024。因此把约一千个候选反复折半，大约十轮就能缩到一个。<code>log₂ n</code> 就是在描述这样的“翻倍 / 折半次数”。具体次数依赖区间写法及最后一次检查，不必死记一个没有前提的公式。</p>'''+box('先问工作量，再问时间','一轮如果还要检查十万个物品，就不是只做了一次比较。二分轮数少，并不保证整个算法一定快。第 10 站会一起算账。'),
'16 个候选，每轮最多留一半，需要几轮缩到 1 个？|若总问最左边的数，哪种回答会让你每次只排除 1 个？|候选数从 1024 变成 2048，大约多几轮？',
'在纸上画一条“16→8→……”的链。','比较 1024 和 2048 的折半链，后者会先经过前者。',
'自己为 1～20 的猜数设计一条最坏情况路线。每次记“问什么、留下谁、为什么”，不使用程序。')
add('从数字队伍到真假队伍','识别一次变化的判断序列，并说出方向。',
'''<p class="lead">二分真正需要的，是判断结果沿某个方向不再反悔。</p><p>对有序数组 <code>[2,4,4,7,9]</code>，逐个问“这个数是否 ≥ 5”，得到 <code>假 假 假 真 真</code>。我们要找的“第一个不小于 5 的位置”，就是第一个真。</p><p>这叫单调的判断。它可以是假后真，也可以是真后假，还可以全假或全真。不能出现假→真→假这种反复变化。</p>'''+table(['判断对象','判断问题','形状'],[['升序数组的位置 i','a[i] ≥ x 吗？','假 → 真'],['升序数组的位置 i','a[i] ≤ x 吗？','真 → 假'],['任意正整数 x','x 是偶数吗？','反复变化，不适合边界二分']])+'''<p>原始数列有序是常见的充分条件。以后输入可以完全无序，只要“候选答案从小到大排列时，check 的真假”是单调的，就可能二分答案。</p>''',
'把 [2,4,4,7,9] 对“≥4”的判断写成真假队伍。|“等于 4”得到的队伍只变化一次吗？|全假、全真时，怎样描述“第一个真”的位置？',
'不要只盯数字，给每张卡片贴上真 / 假标签。','等于某个数可能呈现假、真、假；应先找 ≥ 的边界，再验证等不等于。',
'各造一条假→真、真→假、反复变化的序列；说明前两条可删去哪一边，第三条为什么不能照搬。')
add('重复元素：遇到了，不等于找到了边界','把“任意命中”和“第一个符合条件”分开。',
'''<p class="lead">找到了一个 4，任务可能还没完成。</p><p>数组 <code>[1,4,4,4,8]</code>，中间的元素是 4。若只问“4 在不在”，现在可以结束；若问“第一个 4 的下标”，左边还可能有更早的 4。</p><p>统一换个问题：寻找第一个 <code>a[i] ≥ x</code> 的位置 p。若 <code>p &lt; n</code> 且 <code>a[p] == x</code>，才说明 x 存在，且 p 是它第一次出现的位置。否则 p 只是插入位置。</p><p>找不到不代表随意输出 -1。边界函数可以约定返回 n，表示所有元素都小于 x。存在性题再按题意转成“未找到”。这两个层次要分清。</p>'''+box('最小区分反例','[4,4]：任意命中可以返回任一位置，第一次出现只能返回最左边。再试 [3,7] 查 5：找到边界不代表找到相等元素。'),
'在 [1,4,4,4,8] 中，命中下标 2 后，左边还可能有什么？|查找 6 时，第一个 ≥6 的位置存在，6 本身存在吗？|如果 p==n，能不能直接读取 a[p]？',
'把“找到符合条件的一个”和“证明前面都不符合”分成两件事。','先判断下标是否合法，再读取对应元素；n 是边界位置，不是实际元素。',
'为 x=0、4、6、9 各画真假队伍，手写 p 与“x 是否存在”。代码先不急着写。')
add('两根界桩：每轮都不变的约定','建立“左假右真”的不变式。',
'''<p class="lead">边界会移动，边界的身份不变。</p><p>现在专门找假→真序列里的第一个真。设 <code>lo</code> 指向一个已知的假，<code>hi</code> 指向一个已知的真。两根界桩之间的格子还未确定。每轮开始和结束都坚持这份约定，它叫<strong>循环不变式</strong>。</p><p>数组下标是 0～n−1。为了处理全真和全假，设想 -1 位置贴“假”，n 位置贴“真”。它们是虚拟界桩，不是数组元素。初始化 lo=-1、hi=n；只检测严格位于两者之间的 mid，所以绝不访问 a[-1] 或 a[n]。</p>'''+table(['mid 的判断','能确定什么','移动谁'],[['真','第一个真不会在 mid 的右边；mid 可能就是答案','把真界桩搬到 mid'],['假','mid 及它左边都不可能是第一个真','把假界桩搬到 mid']])+'''<p>注意：hi 不是“最后一个尚未检查的下标”，lo 也不是“当前答案”。定义混用，是很多边界错误的根源。</p><div id="boundary-lab" class="lab"></div>''',
'当 mid 是真，为什么不能把它一起丢掉？|如果所有实际元素是假，最后哪根界桩代表“没有真实答案”？|每次移动后，你还能证明 lo 是假、hi 是真吗？',
'在中点位置画一面旗，问：答案能不能恰好就在这面旗上？','虚拟端点的真假来自约定，实际端点的真假来自检查；不能把虚拟端点拿去索引数组。',
'用 [2,4,4,7,9] 查 ≥4，手推每轮 lo、mid、hi 和判断。然后在实验室逐步核对。')
add('最后只剩相邻两格：为什么能停？','同时证明不漏答案、严格缩小和最终含义。',
'''<p class="lead">“样例没有死循环”，还不是终止证明。</p><p>当 hi−lo&gt;1 时，选严格在两者之间的整数 mid。只把一根界桩移到 mid，新的距离就严格变小。距离是正整数，不会永远下降。直到 hi−lo==1，两根界桩之间已经没有待检查的整数。</p><p>此时 lo 是假，hi 是真，且它们相邻。由单调性，hi 正是第一个真。若 hi==n，就是数组内没有真。这里停下时不必要求 lo==hi，因为两根界桩本来就承担不同身份。</p><h3>把证明说成三句话</h3><ol><li>开始：左假右真的约定成立，目标边界夹在其中。</li><li>过程：每次检查只去掉已证明不需要的一侧，约定继续成立，距离严格变小。</li><li>结束：相邻时无处再藏一个更早的真，hi 就是边界。</li></ol>'''+box('死循环放大镜','只剩两个候选时最容易暴露错误。若某种闭区间写法用了向下取整的 mid，再执行 l=mid，l 可能完全不动。先追踪 [l,r]=[3,4]，再讨论修法；不要随手加一个 +1。'),
'lo=2、hi=4 时，还需要检查哪个位置？|lo=2、hi=3 时，还有没有整数藏在中间？|如果更新后距离没变，你能保证下一轮会不同吗？',
'先数两根桩之间有几格，而不是只比较端点是否相等。','本讲的“左假右真”版本只有在距离大于 1 时才取中点，因此 mid 严格在内部。',
'为 n=0、n=1 的全真 / 全假分别画终止状态，再用自己的话完成三句证明。')
add('变量登记表：把模型翻译成 C++','自己填出关键分支，不把区间规则混用。',
'''<p class="lead">每个变量先有职责，之后才有代码。</p>'''+table(['变量','现实含义','变化规则'],[['lo','已知为假的左界桩','检测到新的假时向右移'],['hi','已知为真的右界桩','检测到新的真时向左移'],['mid','这轮要询问的位置','每轮重新计算'],['n','实际元素数量','搜索过程中不变']])+code('''// 局部思路骨架：填空后再自己封装函数，不是完整题解。
// a 升序；0 <= n <= 10^6；使用有符号整数保存界桩。
long long lo = -1, hi = n;
while (hi - lo > 1) {
    long long mid = lo + (hi - lo) / 2;
    if (a[mid] >= x) {
        /* 谁应当搬到 mid？由你填写 */
    } else {
        /* 谁应当搬到 mid？由你填写 */
    }
}
// 返回谁？这个返回值有可能不是合法数组下标吗？''')+'''<p>先写注释“这里已经确定真 / 假”，再填变量名。不要从别处抄来 <code>mid±1</code> 拼进这个版本。闭区间 [l,r]、半开区间 [l,r) 也可以写对，但它们需要各自配套的不变式、循环条件与返回含义。</p><p>本例使用有符号类型，因为 lo 需要取 -1。<code>vector::size()</code> 是无符号类型；先确认长度在可表示范围内，再转换并存入有符号变量。中点写法也要保证 hi−lo 不溢出。</p>''',
'真分支执行后，哪根桩必须继续保持“真”的身份？|为什么本骨架不需要 mid+1 或 mid−1？|返回边界后，调用者在读 a[p] 之前要查什么？',
'把上一站两种移动动作原封不动翻译成赋值。','这里保存的是已知真假界桩，不是待查闭区间。',
'自己补出局部函数，再写读取数据与输出。测试空数组（仅函数测试）、单元素、重复元素、全假、全真；用线性扫描核对。')
add('四种边界，其实是两个分界','由 ≥ 与 > 的边界推出计数和前驱。',
'''<p class="lead">先找到分界，再决定题目要哪一侧。</p><p>对于升序数组，记 p 为第一个 ≥x 的位置，q 为第一个 &gt;x 的位置。它们都可以按假→真的同一种思路查找。相等的元素恰好占据 [p,q)。</p>'''+table(['要什么','由边界得到','使用前的检查'],[['第一个 ≥x','p','p&lt;n 才能读取元素'],['第一个 &gt;x','q','q&lt;n 才能读取元素'],['最后一个 &lt;x','p−1','p&gt;0 才存在'],['最后一个 ≤x','q−1','q&gt;0 才存在'],['等于 x 的数量','q−p','可以为 0'],['闭区间 [L,R] 中的数量','第一个 &gt;R 的位置 − 第一个 ≥L 的位置','要求 L≤R；否则按空区间处理']])+'''<p>自己画 [1,3,3,3,6]，分别给 p 和 q 插旗。减法数的是两面旗之间的格子，不是值的差。</p>'''+box('不强求 x+1','整数题中查 &gt;x 有时可以转成查 ≥x+1，但 x+1 可能溢出，实数也没有“下一个数等于 x+1”的含义。直接定义 &gt; 更清楚。'),
'在 [1,3,3,3,6] 里，p 和 q 分别停在哪里？|为什么相等数量是 q−p，不是 q−p+1？|查 x=0 时，哪个“最后一个”不存在？',
'画半开区间：左边界包括，右边界不包括。','先数格子，再数下标差；没有元素时两面旗重合。',
'写三个只调用边界函数的小功能：存在性、重复次数、区间计数。用不存在的值与两端以外的值检查。')
add('标准库：理解以后再交给工具','正确使用 lower_bound、upper_bound 和返回迭代器。',
'''<p class="lead">工具替你执行查找，题意与边界仍由你负责。</p><p>对默认升序的 vector，<code>std::lower_bound</code> 找第一个不小于目标的位置，<code>std::upper_bound</code> 找第一个大于目标的位置。需要 <code>&lt;algorithm&gt;</code>。返回的是迭代器，可以理解为“指向某个位置的标记”，不是元素值。</p>'''+code('''// 只展示调用接口；存在性、计数和输出由你完成。
auto it = std::lower_bound(a.begin(), a.end(), x);
// 先比较 it 与 a.end()，再决定能不能读取 *it。
// 对 vector：it - a.begin() 可以得到从 0 开始的位置。''')+'''<p><code>end()</code> 表示末尾之后；找到它不是程序出错，而是范围内没有符合条件的元素。<code>binary_search</code> 只回答存在与否，不能直接给出第一次出现的位置。</p><p>本讲先在默认升序 vector 上使用。更一般的前提是数据相对于查询比较式已分区；换降序或自定义比较器，要重新检查比较方向。不要直接在乱序数据上调用。</p><p>普通算法作用于链表等非随机访问结构时，比较次数少，不意味着移动迭代器也只需对数步。对 set / map 查边界，应认识它们自己的成员函数。详见 <a href="https://eel.is/c++draft/alg.binary.search" target="_blank" rel="noopener">C++ 工作草案：二分查找算法</a>。</p>''',
'it==a.end() 时，*it 有意义吗？|题目要重复数量，只调用 binary_search 够吗？|先排序会不会破坏题目要求的原始位置？',
'先说返回对象代表“位置”还是“值”。','如果需要原编号，可以排序带编号的数据；如果题意依赖原顺序，则未必允许排序。',
'把第 8 站的功能换成标准库版本，并逐项比较输出。保留手写版本，用来解释工具在做什么。')
add('第一次营地检查：正确，也要算得动','算上排序、查询与 check 的全部成本。',
'''<p class="lead">“用了二分，所以 O(log n)”经常少算了大半工作。</p><p>升序数组中查询一次，随机访问每个中点 O(1)，查找 O(log n)，循环只存几个变量，辅助空间 O(1)。若原数据无序，需要先排序，再做 q 次查询，常见总时间为 O(n log n+q log n)。排序一次，不是每问一个值就重新排一次。</p><p>如果只有一次查询，线性扫描 O(n) 可能比“先排序再二分”更合适。若必须保留原数据，复制数组还会额外使用 O(n) 空间。</p><p>以后每轮 check 花 T(n)，答案范围内有 V 个整数候选，总成本一般为 <strong>预处理 + O(T(n) log V)</strong>。这里 log 的对象是答案范围，不一定是数组长度。</p>'''+table(['营地 A 通关证据','验证任务'],[['能解释','用自己的话说明为什么真分支保留 mid'],['能实现','遮住骨架，写第一个 ≥x 的函数'],['能测试','最小输入、重复元素、所有元素都不满足'],['能迁移','把存在性改为 [L,R] 的数量查询']])+'''<p>四项里有一项不稳，就回到对应站补一次。选择题答对或看完讲义，都不会自动标为掌握。</p>''',
'一轮 check 扫 n 个数，总共二分约 30 轮，工作量该怎样写？|q 次查询是否需要做 q 次排序？|只有一次查找、数组很小，二分一定更划算吗？',
'分成“开场只做一次”和“每轮 / 每次查询都做”的两本账。','乘法只用于确实重复发生的工作；空间要数同一时刻保存的东西。',
'完成营地 A 四项验收，留下你自己的证明和一个专门抓边界错误的测试。每次只补一项。')
add('二分答案：先问“这样够不够”','把最优化问题改成单调的可行性问题。',
'''<p class="lead">不知道最小背包多大，可以先问：容量 10 够不够？</p><p>直接求最优值有时很难，但给一个候选值，判断是否能完成任务更容易。比如容量越大，原来能装下的方案仍然能装下；可行性呈假→真。最小可行容量，就是第一个真。</p><p>与数组查找不同，mid 此时代表候选容量，不再是数组下标。输入中的数字不一定有序，也不一定包含最优答案。</p><h3>一张四格建模卡</h3>'''+table(['格子','必须写清'],[['答案变量 x','是什么量、什么单位、整数还是实数'],['check(x)','一句完整的是非问题；“存在某个合法方案吗”'],['单调方向','x 变大，原来那个可行方案还能不能继续用'],['范围与端点','最小 / 最大可能值；是否保证有解；界桩的真假']])+'''<p>另一个方向：要求每两棵树间距至少 d，d 越大越难做到，是真→假。要求“最小化最大值”或“最大化最小值”常提示二分，但这些文字本身不构成证明。</p>''',
'背包容量增大时，原来的装法为什么仍然合法？|要求间距从 3 增加到 5，是变松还是变紧？|你的 mid 现在代表容量、位置还是数量？',
'保留原方案不动，只改变题目给它的限制。','证明可行性时，不必证明同一个贪心程序每次都选同一个方案。',
'为“最小容量”和“最大间距”各写四格卡，只画真假方向，不写二分循环。')
add('先做好裁判：check 是一个独立问题','分开证明外层单调与内层判断正确。',
'''<p class="lead">二分问得再聪明，裁判答错了，结果仍会错。</p><p><code>check(x)</code> 必须准确回答“是否存在合法方案”。找到一个合法方案可以证明可行；某一种随意尝试失败，却不能证明所有方案都失败。要靠贪心证明、动态规划或其他可靠算法，才能得到否定结论。</p><h3>先拆开调试</h3><ol><li>暂时不写二分。用很小的输入枚举所有合法方案，得到可信的暴力裁判。</li><li>给几个固定候选 x，比较快速 check 与暴力裁判。</li><li>确认 check 正确，再接上二分。</li><li>最后比较完整二分程序和直接枚举候选值的结果。</li></ol><p>一次 check 里用的计数、前缀数组、访问标记、DP 状态，下一次要重新初始化。否则后一次判断依赖前一次调用，函数就不再是在回答同一个问题。</p>'''+box('两个证明，缺一不可','外层：候选值变化时，可行性方向不变。内层：这个算法恰好判断了题目允许的所有可能方案。只画出几次 check 的真假，不能替代任一证明。'),
'“我这样摆不下”能推出“所有摆法都不行”吗？|同一个 x 连续调用两次，结果是否应该相同？|如果单调性正确，但 check 贪心错误，二分能自动修正吗？',
'想想：有没有第二种合法摆法被裁判漏掉？','调用前后都核对变量职责；检查上一轮是否留下了状态。',
'从接下来的练习任选一道，先独立完成 3 次固定 x 的手推判定。说明每次“否”的依据。')
add('切木条：先推“需要几刀”','从一根木条建立整数 check，再合并多根。',
'''<p class="lead">想让最长的一段尽量短，先固定允许长度 x。</p><p>教学任务：n 根正整数长度木条，可以在任意位置切，总共最多切 K 刀。求一个最小的正整数上限 x，使所有段都不长于 x。切开一根不会影响另一根，因此可以逐根计算最少需要几刀，再相加。</p><p>长度 a，分成 s 段时，总长度 a≤s·x 是必要条件；若 s 足够，均分能让每段≤x，因此也是充分条件。最少段数是向上取整 a/x，刀数比段数少 1。请先自己写出式子，再打开推导提示。</p><p>固定 x 后只需 O(n) 扫描。x 增大，每根需要的刀数不会增多，check 是假→真。候选范围 1～max(a)，不切时上界必然可行；0 是不可取长度，可以作虚拟假界桩但不能参与除法。</p>'''+box('一个关键反例','a=6、x=3：画出切点。若你直接用 a/x 当刀数，会在恰好整除时多算。再与 a=7、x=3 对比。')+'''<p>迁移原题：<a href="https://atcoder.jp/contests/abc174/tasks/abc174_e" target="_blank" rel="noopener">AtCoder ABC174 E · Logs</a>。原题输出最优最长段长度向上取整的整数，适合进一步解释“搜索整数上限”的含义。</p><div id="cuts-lab" class="lab"></div>''',
'6 分成每段至多 3，需要几段、几刀？|长度上限放宽后，为什么原切法仍合法？|K=0 时，哪个输入量能直接给出边界答案？',
'段数与刀数差 1；先画切点，别急着写除法。','对正整数 a、x，ceil(a/x)−1 可整理成 (a−1)/x 的整数除法。相加时使用足够宽的类型，超过 K 即可停止。',
'自写 check，再接二分。至少测恰好整除、K=0、只有一根；用长度不超过 10 的小输入逐个枚举 x 核对。')
add('分书与装箱：最小化最大的那一组','证明顺序分段贪心，识别负数与组数限制。',
'''<p class="lead">顺序不能乱，每一组也不能装得太重。</p><p>教学任务：n 本书按既定顺序摆放，每本页数是非负整数。把它们切成至多 k 个非空连续组，1≤k≤n，希望最大组页数和最小。不能排序，因为连续组依赖原来的顺序。</p><p>固定每组上限 x，从左到右尽量把下一本放进当前组；放不下才开新组。若某一本大于 x，直接不可行。其余情况下，统计最少组数是否≤k。</p><h3>为什么“尽量装满”可以当裁判？</h3><p>第一组贪心取的前缀最长，任何合法第一组都不会比它更靠后。继续比较第 2 组、第 3 组的结束位置：非负页数保证，从更靠后的起点出发不会因为去掉前面一些书而增加负担。因此同样组数下贪心覆盖得至少一样远，它用的组数最少。</p><p>若题目要求恰好 k 组，且允许任意切分、每组非空、n≥k，已有不足 k 组时可以继续拆组；非负数保证拆后不超上限。这个结论换成负数就不能照搬。</p>'''+box('让前提自己说话','[6,−2]、上限 4：一组总和是 4，单本 6 并不能证明不可行。非负前提被破坏后，原贪心也可能过早分组。')+'''<p>下界可从 max(a) 开始，上界 sum(a) 一定够。全零时答案可能是 0，不能照抄上一题的正整数下界。</p>''',
'在 [4,2,4]、k=2 中，上限 5 与 6 分别需要几组？|为什么这题不能先排序？|把“非负”删除后，哪一步证明先失效？',
'记录每组结束的位置，不要只记录总组数。','比较任意合法方案与贪心：同样用一组，谁能覆盖更长前缀？',
'先在 n≤8 时枚举切缝作暴力裁判，再写贪心 check。测试单组、每本一组、全零、刚好等于上限。')
add('种树：最大化最小距离','在真→假方向维护最大可行值。',
'''<p class="lead">给树更多间距，种下同样多棵就更难了。</p><p>给 n 个可种树坐标，要求挑 m 个位置，2≤m≤n，最大化相邻两棵的最小间距。先排序坐标。固定距离 d，第一棵放最左边；下一棵放在距上一棵至少 d 的最早可用位置。</p><p>贪心为什么可靠？任何合法方案的第一棵不早于最左位置。若贪心第 j 棵不晚于另一方案第 j 棵，则另一方案的第 j+1 棵到贪心第 j 棵也至少有 d；贪心选最早合法点，自然不会更晚。如此下去，有别的方案能放 m 棵，贪心也能。</p><p>可行性为真→假。令 lo 为已知可行距离，hi 为已知不可行距离；中间可行就提高 lo，否则降低 hi。相邻时返回 lo，身份与“第一个真”版不同，别只记字母名。</p><p>整数坐标下可以用 lo=0、hi=最大坐标−最小坐标+1。m≥2 保证 hi 不可行；坐标差和 +1 要能存下。若 m=1，最近两棵的距离没有定义，需要另看题意。</p><div id="spacing-lab" class="lab"></div>''',
'坐标 [1,2,4,8,9]，放 3 棵，d=3 与 d=4 分别怎么摆？|为什么选较早的下一棵不会挤占后面更多空间？|结束时要可行的一侧，还是不可行的一侧？',
'把两种方案的第 1、2、3 棵对齐，逐个比较坐标。','证明依靠“贪心位置不晚于其他方案”，不能只说“看起来最省地方”。',
'独立完成贪心与二分。用小 n 枚举所有 m 个位置作核对，并测试重复坐标（若允许）、m=2、m=n。')
add('范围与整数安全：界桩也需要证明','处理无解、零答案与大数运算。',
'''<p class="lead">搜索区间写错了，答案可能从一开始就在围栏外。</p><p>每个端点都写一句依据：为什么这个值一定不行？为什么另一个一定行？“很大的数应该够了”不是依据。若没有保证存在可行值，先检测合法最大候选；仍不可行时按题意报告无解。</p><p>没有现成上界时，可从一个合理起点不断翻倍，直到找到可行值，再二分。但必须保证解确实存在，或设定合法上限与溢出保护。全不可行时，盲目翻倍不会凭空造出答案。</p>'''+table(['风险','检查动作'],[['(l+r)/2 溢出','本讲有限范围使用 l+(r−l)/2，并另外确认 r−l 可表示'],['int 乘完才交给 long long','乘法开始前提升操作数类型，不是最后才转换结果'],['mid*mid 超范围','正 mid 时可改比较 mid≤N/mid；单独处理 0'],['累计刀数 / 总页数太大','先估计 n×单项上界，选足够宽的类型或阈值截断'],['虚拟哨兵参与 check','循环必须只取实际候选；除数不能为 0']])+'''<p>使用 long long 不是“永远不会溢出”。先根据约束估计最大中间值。若端点跨越整个有符号 64 位范围，差值也可能溢出，需要更宽的中间运算或合适的安全中点工具。</p>''',
'“上界是所有页数之和”为什么比“上界随便写一百万”可靠？|如果 max(a)=0，前一题的正整数搜索范围还成立吗？|两个 int 相乘后才赋给 long long，乘法在哪种类型中发生？',
'给每一个数写上最大可能值，尤其是乘积与累计和。','检查的是表达式求值时的类型，不只是左边接收变量的类型。',
'给切木条、分书、种树各写端点证明。再为其中一题造一个超过 32 位累计范围的合法输入。')
add('实数二分：精度是一份约定','按范围与误差预算选轮数，区分整数与实数。',
'''<p class="lead">两根界桩在实数轴上，可以永远不相邻。</p><p>教学例子：求非负实数 A 的平方根。固定 x≥0，判断 x²≥A，是假→真。起始范围 [0,max(1,A)] 包住根；A=0 可以直接处理。每次取实数中点，按判断保留包含根的一半。</p><p>实数没有“相邻两个整数”的停止方式，也不能使用 mid±1。若初始宽度为 W，理想精确算术下做 t 轮，宽度为 W/2ᵗ。由题目允许的绝对误差反推 t，再留一定余量。相对误差要求还需结合答案尺度。</p><p>浮点数精度有限。范围过大时，mid 可能舍入成端点，继续循环也不再缩小。可以用固定轮数，并检查中点是否等于某端点；平方运算也要考虑浮点范围。不要声称“80 次适合所有范围”。</p>'''+box('一份具体预算','若范围宽度不超过 10⁹，60 次折半的理想宽度约 8.7×10⁻¹⁰；但 double 在 10⁹ 附近的表示间距约 10⁻⁷ 量级，不能据此承诺 10⁻¹⁰ 的绝对误差。最终还受浮点运算、check 稳定性和输出位数影响。')+'''<p>如果输入只有两位小数且问题允许以“分”为整数单位，可以考虑乘 100 后做整数问题。但只有题目确实允许这种离散化，才能这么做。</p>''',
'为什么实数二分不能等 hi−lo==1？|若宽度为 8，做 3 次折半后还剩多宽？|输出四舍五入与判断可行性的精度，是同一件事吗？',
'先只算区间宽度，不急着算平方根的具体小数。','最终误差由多处共同决定：搜索范围、运算精度、判定误差、输出格式。',
'自己实现非负数平方根实验，选 A=0、0.25、2。记录每轮宽度，并说明固定轮数是怎样从误差要求选出来的。')
add('二分 + 图搜索：水位升高以后能通行吗？','把一个候选值变成一张可走的图。',
'''<p class="lead">外层猜水位，内层只负责回答能否到达。</p><p>教学任务：网格每格有高度。水位 h 时，高度≤h 的格子能进入，只能上下左右走。求从起点到终点所需的最低水位。起点和终点本身也必须可进入。</p><p>固定 h，先排除过高格子，再用 BFS 或 DFS 检查连通性。水位增加，只会新增可用格子，不会删掉原来的路，因此是假→真。check 为 O(行数×列数)，每次访问标记必须重置。</p><p>答案一定是网格中某个高度：两相邻不同高度之间，能走的格子集合完全一样。因此可将所有高度排序去重，二分它们的下标。不要误把“二分高度值”与“二分候选高度数组的位置”混为同一变量。</p><p>矩形网格全部开放时可以连通，最大高度就是可行上界；若额外有永久障碍，则需另查是否存在任何路径。</p>'''+box('先备好工具','本题需要队列与 BFS，或能防重复访问的 DFS。若还没学图搜索，先只画三张水位不同的可走格子图，把本题停在建模阶段。')+'''<p>小网格：第一行 1、8、2；第二行 2、3、4；从左上到右上。试 h=3、4、8。它能区分“找最短步数的路”和“最低水位下存在一条路”。</p>''',
'水位从 3 增加到 4，原来能走的路径会失效吗？|起点高度高于 h 时，BFS 应不应该直接入队？|两个候选高度之间没有新格子开放，答案会藏在那里吗？',
'分别涂出高度≤h 的格子，再尝试连线。','单调性来自可走集合只增不减，与 BFS 的遍历顺序无关。',
'先画小网格手推，再写只接收 h 的可达性函数。测起终点同格、必须绕路、起点未开放。', '第 11～16 站；队列、BFS 或 DFS')
add('二分 + 最短路：代价改变，路线也会改变','用最短路作 check，避免固定一条路线。',
'''<p class="lead">最便宜的路，可能随着价格变化而换一条。</p><p>教学模型：进入普通格花 1，进入墙格花正整数 x。给定时限 T，问最大的 x，让起点到终点仍能在 T 内到达。固定 x 后，边权非负，可以用 Dijkstra 求最短时间，再判断≤T。</p><p>证明单调时，不要追踪“程序选的那条最短路”。取一个较大 x 下的可行路径，降低 x 后，这条路径的总成本不会增加，所以较小 x 仍可行。于是 check 真→假。</p><p>路线可能切换：一条路的成本为 2x+1，另一条为 x+5。自己代入几个 x，比一比谁更便宜。只在 x=1 时找一次路径、以后沿用那条路径计价，会漏掉更优选择。</p><p>堆优化 Dijkstra 一次常写 O((V+E)log V)，外层再乘 log U，U 为候选整数范围大小。这里 V 表示顶点数，不能与“答案范围”混记。</p><p>原题 <a href="https://atcoder.jp/contests/abc020/tasks/abc020_c" target="_blank" rel="noopener">AtCoder ABC020 C · 壁抜け</a> 保证必须经过墙且 x=1 可行，从而有有限最大值。若改编题存在全白可行路径，又没限制 x 的最大值，答案可能无上界，不能擅自取 T。</p>''',
'降低墙价后，原来的一条可行路为什么仍可行？|成本 2x+1 与 x+5 的两条路，谁总是更好？|若完全不需要经过墙，为什么不能直接断言最大 x=T？',
'分开“某条路的成本”与“所有路径中的最小成本”。','证明单调只需让原可行路径继续合法，不需要最优路径保持相同。',
'先用两条路径的代价式画小表，再实现固定 x 的最短路。还没学 Dijkstra 时，只完成纸面建模。','第 18 站；图、非负权最短路、优先队列')
add('二分 + 调度：高度变成截止时间','把限制转换成能排序的紧迫程度。',
'''<p class="lead">猜了一个最高高度，就得到每个气球最迟什么时候要处理。</p><p>教学模型：第 i 个气球初始高度 Hᵢ，每秒上升 Sᵢ&gt;0；在时刻 0、1、…、n−1 各处理一个。希望处理时的最大高度尽量小。固定上限 X，若某个 Hᵢ&gt;X，立即不可行；否则每个气球的最晚处理时刻是 ⌊(X−Hᵢ)/Sᵢ⌋。</p><p>现在子问题变成：每件任务耗一个时刻，能不能都赶在截止时间前？按截止时间从早到晚排，在第 j 个时刻（从 0 开始）处理第 j 个任务，检查它的截止时间是否≥j。</p><h3>为什么先做更急的？</h3><p>若一个合法安排让较晚截止的任务 A 排在较早截止的 B 前面，交换这对相邻任务。B 提前不会迟到；A 移到 B 原来的时刻，该时刻不晚于 B 的截止时间，也不晚于 A 的截止时间。因此可以逐步换成截止时间顺序。</p><p>一次 check 计算并排序，O(n log n)。可用 max Hᵢ−1 为假界桩，max Hᵢ+max Sᵢ·(n−1) 为真界桩；先确认乘积范围。</p><p>迁移：<a href="https://atcoder.jp/contests/abc023/tasks/abc023_d" target="_blank" rel="noopener">AtCoder ABC023 D · 射撃王</a>。先自己完成截止时间转化，再读完整题面约束。</p>''',
'X=10、H=4、S=3 时，最晚可在哪个整数时刻处理？|截止时间 [0,0,2] 与 [0,1,2] 有什么区别？|如果排序改为“上升最快的先处理”，交换证明还成立吗？',
'先写不等式 H+S·t≤X，再解出 t 的范围。','时刻从 0 开始；比较的是排好序后的截止时间与安排时刻。',
'自己造 3 个气球，枚举 6 种处理顺序，核对固定 X 的调度判断，再接二分。','第 11～16 站；排序、整数除法、简单交换论证')
add('二分 + 差分：第几个请求开始失败？','把请求前缀的单调性与区间更新组合。',
'''<p class="lead">二分的不一定是价格，也可以是时间线上的位置。</p><p class="callout">先修补课：<a href="../前缀和差分探险/前缀和与差分探险指南.html#lesson-6">一维差分第 6～8 站</a>。先会单独完成区间修改与恢复，再把它放进 check。</p><p>教学任务：n 天各有容量 cᵢ。m 个订单按顺序到来，每个订单在连续日期 [l,r] 每天占用 d&gt;0。不能拒绝前面的订单，求第一个使容量不足的订单编号；若全部可接受，报告“全部通过”。</p><p>先看一组具体订单：三天各有 3 间教室。第 1 份在第 1～2 天各借 2 间，第 2 份在第 1 天借 2 间。只接第一份时，每天需求是 [2,2,0]，都够用；接前两份时，变成 [4,2,0]，第 1 天不够用了。注意，失败的是第 2 份订单，超量发生在第 1 天，两个编号不同。</p><p>把“接前 k 份后，每天都够不够用”写成一个判断，叫 check(k)。因为订单只增加占用，某天一旦不够，再接订单也不会自动变够。因此随着 k 增加，check 会先通过、后失败；我们要找第一次失败的位置。若允许后来订单撤销需求，这个变化方向就需要重新检查。</p><p>直接逐天加每个订单可能太慢。差分数组让一次区间加变成两处标记：l 处加 d，r+1 处减 d；最后做前缀和恢复各天需求。给数组留出 r+1 的空间。一次检查 O(n+k)，上界为 O(n+m)，总时间 O((n+m)log(m+1))。</p><p>check(0) 可行。先测 check(m)，若也可行就无需找失败边界；否则维护“可行订单数 lo”和“不可行订单数 hi”，相邻时 hi 是第一份失败订单编号（订单从 1 开始）。每次必须清空工作差分数组，原订单数据保留。</p>'''+box('从最小例子看前缀','容量 [3,3]；订单 A：第 1～2 天各加 2，订单 B：第 2 天加 2。先分别检查前 0、1、2 个订单，不要把“第几天超量”和“第几个订单失败”混在一起。'),
'添加非负需求的订单，已经超量的那天会自动恢复吗？|check 返回失败时，题目要输出天数还是订单编号？|上一次 check 的差分数据残留，会怎样影响下一次？',
'在纸上分两排记：横轴一排是日期，另一排是订单顺序。','外层查订单前缀长度；内层扫描日期。两个下标承担不同角色。',
'先用逐天加的慢裁判，再写差分裁判并逐 k 比较。测第一单失败、最后一单失败、全部通过。','第 11～16 站；前缀和、差分')
add('二分 + 前缀和：最大平均值','把平均数门槛转成子段和，避免枚举全部区间。',
'''<p class="lead">平均值至少 x，可以改问：减掉 x 后，总和能否不小于 0？</p><p class="callout">先修补课：<a href="../前缀和差分探险/前缀和与差分探险指南.html#lesson-1">前缀和第 1～4 站</a>。先能解释区间差，再进入最大平均值的变换。</p><p>教学任务：长度 n 的数组（可含负数），选一个长度至少 L 的连续非空子段，1≤L≤n，最大化平均值。固定实数 x，令 bᵢ=aᵢ−x。对子段长度 k，平均值≥x 等价于 Σaᵢ−kx≥0，即 Σbᵢ≥0。</p><p>令 s[0]=0，s[r] 是前 r 项 b 的和。以 r 结尾的子段满足长度至少 L，其左前缀下标 j 必须在 0～r−L，子段和 s[r]−s[j]。要让差最大，就选这些合法 j 中最小的 s[j]。</p><p>从 r=L 扫到 n，维护合法前缀的最小值。每一步先把新合法的 s[r−L] 加入考虑，再判 s[r]−最小前缀是否≥0。这样 check 为 O(n)，无需枚举 O(n²) 个子段。</p><p>候选范围可取 min(a) 到 max(a)，可行性真→假。端点是包住最优值的闭区间：最大端可能恰好可行，不要冒称它必然是假。实数更新只需始终把最优值夹住，按第 17 站设置误差与轮数。</p>'''+box('长度条件藏在下标里','如果错误地允许 j=r，就选了空子段，和恒为 0，会把本来不可行的 x 也判断为可行。维护“所有前缀最小值”之前，先写出 j 的合法范围。'),
'为什么要对每个元素都减 x，而不是对子段总和只减一次 x？|长度至少 L 时，j 为什么不能超过 r−L？|如果先判定、后加入 s[r−L]，会漏掉哪种长度？',
'把“平均数=总和/个数”两边乘正的个数。','前缀下标 j 表示被减掉的前 j 项；子段长度为 r−j。',
'用 [1,5,2,6]、L=2，固定 x=4 手推 b、s 和合法最小前缀。再用所有子段枚举验证小数组。','第 17 站；前缀和、不等式、区间下标')
add('分数规划：最大比值不等于挑最大的比值','理解 ΣA/ΣB 的阈值变换与选择约束。',
'''<p class="lead">混合以后的比例，要看每一份有多重。</p><p>教学模型：每件物品有贡献 Aᵢ 和正权重 Bᵢ，必须恰好选 K 件，最大化 ΣAᵢ/ΣBᵢ。固定候选比值 x，因分母为正，有 ΣAᵢ/ΣBᵢ≥x ⇔ Σ(Aᵢ−xBᵢ)≥0。</p><p>所以给每件物品一个随 x 改变的得分 Cᵢ=Aᵢ−xBᵢ。如果除恰好选 K 件外没有其他限制，最大的 K 个 Cᵢ 的和就是所有合法选择中最大的变换后总和。用它是否≥0 判断可行。</p><p>不要按单件 Aᵢ/Bᵢ 排序后永久挑前 K 个。比如三件物品 (A,B) 为 (1000,100)、(9,1)、(800,100)，选两件。亲自比较各组合的比值，就能发现单件排名不够决定最优组合。每次 x 改变，C 的排名也可能改变。</p><p>一次排序 O(n log n)，实数二分 t 轮总 O(t n log n)。所有 B&gt;0 时，整体比值是单件比值的加权平均，可以用单件比值的最小值、最大值包住最优值。</p><p>迁移：<a href="https://atcoder.jp/contests/abc034/tasks/abc034_d" target="_blank" rel="noopener">AtCoder ABC034 D · 食塩水</a>，选择固定数量的容器，最大化混合后的浓度。百分数单位要从头到尾一致。</p>''',
'为什么分母为正是移项时的重要条件？|选 K 个最大的变换得分，依赖题目没有哪类额外限制？|当 x 改变时，为什么不能沿用第一次排序？',
'先把整个分式写出来，再乘总分母，不要把它拆成单件比值之和。','如果有相邻限制、容量限制等，最大的 K 个未必合法，内层裁判就要换。',
'枚举三件物品选两件的所有组合，再固定两个 x 比较变换得分。只在关系式能独立推出后开始实现。','第 17、22 站；加权平均、排序、不等式')
add('二分 + DP：可行方案有相邻限制','让状态回答受约束的最大变换得分。',
'''<p class="lead">不能随便挑最高分时，让状态记住前面的选择。</p><p>教学任务：n≥2 张按顺序排列的卡片，任意相邻两张至少选一张。希望所选卡片的平均值最大。固定 x，仍可用 bᵢ=aᵢ−x 转成“存在合法选择使总得分≥0”。但不能直接只选正得分，因为可能连续漏掉两张。</p><p>准备两个状态：Sᵢ 表示前 i 张合法且第 i 张已选的最大得分；Nᵢ 表示前 i 张合法且第 i 张未选的最大得分。若这张选了，上一张选不选都行；若这张不选，上一张必须选。请先自己写出两条转移，再打开教练提示。</p><p>边界从第一张开始：S₁=b₁，N₁=0。n≥2 时，最终合法状态不可能全不选。每次 check 重新设置初值，并用上一层两个旧值计算新值，不要刚更新 S 就误拿新 S 算 N。滚动状态可用 O(1) 辅助空间，每次 O(n)。</p><details><summary>教练备课：推导核对（孩子尝试后再开）</summary><p>Sᵢ=max(Sᵢ₋₁,Nᵢ₋₁)+bᵢ；Nᵢ=Sᵢ₋₁。末尾两种状态都合法，检查它们的最大值≥0。若改成 n=1 或其他选择规则，要重新处理空选择与初值。</p></details><h3>再向上走：中位数也能变换</h3><p>对“偏小中位数”（选 k 个数后取第 ⌈k/2⌉ 小），判断它是否≥整数 x：把≥x 记 +1，&lt;x 记 −1。需要 +1 的数量严格超过 −1，因此合法选择的最大得分必须<strong>&gt;0</strong>，不是≥0。偶数长度正好一半时，是最能区分的反例。</p><p>原题核对：<a href="https://atcoder.jp/contests/abc236/tasks/abc236_e" target="_blank" rel="noopener">AtCoder ABC236 E · Average and Median</a>。本题可分两次学习，先做平均值，隔天再推中位数。</p>''',
'如果第 i 张不选，上一张还能不选吗？|为什么只挑 bᵢ&gt;0 的卡片可能违法？|两个数 [1,10] 的偏小中位数达到 5 吗？+1 与 −1 的总分是多少？',
'先列出相邻两张的四种选 / 不选组合，划掉不合法的一种。','状态先按“最后一张选没选”分组；中位数则先把奇数个和偶数个分别数清。',
'对 n≤8 枚举所有选法，并排除连续两张不选。逐个阈值核对 DP；平均值和中位数分开验收。','第 17、22 站；线性 DP、状态定义、滚动数组')
add('二分在 DP 内部：最长上升子序列','识别优化转移中的有序结构，不把它叫二分答案。',
'''<p class="lead">有时二分没有猜最终答案，只是在帮 DP 找位置。</p><p>任务：找严格上升子序列的最大长度；子序列保留原先后顺序，可以跳过元素。朴素 DP 可记录“以第 i 个元素结尾的最长长度”，枚举所有更早且更小的元素，O(n²)。</p><p>另一种记录方法：tail[len] 表示目前能构成的长度为 len 的严格上升子序列，其末尾的最小可能值。相同长度时，末尾越小，越容易接上未来的新元素。</p><p>这些最小末尾值严格递增：一条长度 len+1 的上升子序列去掉最后一个数，会留下一个更小的长度 len 末尾；最小的长度 len 末尾只会更小。因此 tail 可以二分。</p><p>读到 x，找 tail 中第一个≥x 的位置，用 x 改善对应长度的最小末尾；若没有，才能延长长度。严格上升时相等不延长。若改成最长不下降，边界要改成第一个&gt;x，并重新说明为什么。</p>'''+box('tail 不一定是一条真实子序列','依次读 3、5、6、2，tail 最后可能是 [2,5,6]，但 2 在原序列最后，不能放到 5、6 前面。各位置代表不同方案的最优末尾；若题目要输出实际方案，还需要额外记录前驱。')+'''<p>整体 O(n log n)，额外空间 O(n)。排序原数组会破坏子序列顺序，不能作为这题的捷径。</p>''',
'严格上升时，[2,2] 能否把长度延长到 2？|tail[2] 表示第 2 个原元素，还是长度为 2 的最小末尾？|tail 中每个数都存在，就能证明它们共同组成原序列的一个子序列吗？',
'每个状态旁都写完整句子“某种长度的最小末尾”。','一个数组可以存很多不同方案的代表；不能默认这些代表来自同一条路径。',
'手推 [3,5,6,2,4] 的每次 tail 变化，先实现 O(n²) 版本作对照，再独立实现二分优化。','第 8～10 站；子序列、基础 DP')
add('第 K 小：把“找数”换成“数够了吗”','允许重复，利用阈值计数的单调性。',
'''<p class="lead">想知道第 K 小是多少，可以先问：不大于 x 的有几个？</p><p>教学任务：两个整数数组 A、B，从各取一个数相加，形成 n×m 个带重数的配对和。求第 K 小，1≤K≤n·m；不同下标形成的相同和值仍各算一个。</p><p>固定 x，计算 count(x)=满足 Aᵢ+Bⱼ≤x 的配对数量。x 增大，原来符合的配对仍符合，所以 count≥K 是假→真。第一个使数量达到 K 的 x，就是第 K 小；不能要求 count 恰好等于 K，因为重复值会让数量跳跃。</p><p>将 B 排序。对每个 Aᵢ，利用 upper_bound 找 B 中≤x−Aᵢ 的数量，然后累加，一次 O(n log m)。外层二分整数和值范围，最小和 min(A)+min(B)，最大和 max(A)+max(B)。端点相加、x−Aᵢ、n·m 都要估计数值范围。</p><p>如果两边都排序，随着 Aᵢ 增大，B 的合法右边界只会左移，还可用双指针把每次计数降到 O(n+m)。先写对二分计数，再决定是否值得优化。</p>'''+box('最小反例','A=[1,1]，B=[2,2]。配对和都是 3；count 从 0 直接跳到 4。若 K=2，为什么仍然有第 2 小，却可能永远找不到 count==2？'),
'重复和值按数值去重后，还是同一道“带重数”的题吗？|为什么要找 count≥K 的第一个位置？|对固定 Aᵢ，为什么查询的是 B≤x−Aᵢ？',
'把配对按 (i,j) 编号，即使和一样也不要合并。','第 K 小的阈值性质是：小于它时不够 K 个，达到它时至少有 K 个。',
'对两个长度不超过 6 的数组显式生成并排序所有配对和，逐个 K 核对；加入负数与重复值。','第 8～16 站；排序、计数、可选双指针')
add('调试实验室：先抓住第一次偏差','把错题分为模型、裁判、边界与数值四层。',
'''<p class="lead">不要一见 WA，就把所有 ≤ 都换成 &lt;。</p>'''+table(['现象 / 怀疑层','最小验证动作','用什么区分'],[['答案目标错','先问输出是下标、数量、数值还是订单编号','数组值与下标明显不同的输入'],['check 错','暂时拆掉二分，对固定 x 和暴力比较','枚举所有小方案'],['边界更新错','记录 lo、mid、hi、check(mid)、新区间宽度','空范围、单元素、两元素'],['严格性错','比较等于阈值时是否可行','恰好整除、刚好容量、重复元素'],['状态残留','同一输入按不同顺序调用 check','check(a)、check(b)、check(a)'],['大数或精度错','记录中间值上界与类型','大累计值、接近阈值的实数']])+'''<h3>对拍也要有可信裁判</h3><p>“对拍”是让快速程序和简单的慢程序比较同一批小输入。慢程序最好直接枚举合法方案，不要复制同一个贪心思路，否则两边可能犯同样的错。记录随机种子和失败输入，再尽量删减成最小反例。</p><p>一次只修最结构性的一个问题。修好后重新跑：能区分新旧想法的关键反例、极端 / 边界、最小输入。若仍错，再看第二层。</p>'''+box('局部错误代码的纸面诊断','某程序在 l&lt;r 时算 mid=(l+r)/2，判定可行便 l=mid，想找最大可行值。只给它 l=3、r=4 且 check(3)=真，就能先检查“是否移动”，不需要一百个随机数据。'),
'如果每个固定 x 的裁判都错，先改二分端点有意义吗？|两份程序共享同一个错误贪心，对拍通过能证明什么？|出错输入很大时，你能删掉哪些元素而仍保留错误？',
'先固定一个 x，把外层循环从诊断中拿走。','第一处与手推不同的状态，比最后的错误输出更接近根因。',
'选一份自己写过的程序，设计三类测试并记录第一轮偏差。改对后再由自己写“错在哪里、为什么、下次怎么查”。')
add('选学远眺：很多查询一起二分','认识离线并行二分，分清必修与拓展。',
'''<p class="lead">当很多问题共享同一条时间线，重复建图可能才是最贵的部分。</p><p>教学模型：无向图按时间顺序只添加边，多次询问一对顶点最早在第几次加边后连通。单个询问的连通性随时间是假→真。可以二分时间，再用并查集检查，但每个询问单独重建很多次会重复劳动。</p><p>离线并行二分的一种做法：每轮给所有尚未收敛的询问各算 mid，把它们按 mid 分桶；清空并查集，从早到晚添加边。走到时间 t 时，一起检查桶 t 中的询问，更新各自的界桩。下一轮重新清空并查集，再扫描一次。</p><p>这里“并行”是把查询组织在同一轮批处理，不要求电脑开多个线程。若 n 个顶点、m 次加边、q 个查询，朴素分桶实现每轮大致 O(n+m+q) 外加并查集操作成本，共 O(log(m+1)) 轮。精确分析还应包括初始化与分桶空间。</p><p>时间 0 要单独判断（同一顶点已连通）；到时间 m 还不连通的查询，先标为无解。其余查询才有真实的一假一真端点。</p><p>另有“整体二分”用于把查询按答案范围分治、维护或撤销贡献，具体实现与此不完全相同。当前先认识共享计算的机会，不把术语当成已掌握。</p>'''+box('拓展门槛','这是提高后的延伸，不是二分入门的必修，也不代表提高组只考这些。先能独立完成基础 check、并查集与单次离线扫描，再学习批处理。'),
'单个查询为什么能按时间二分？|同一轮的多个 mid 排好后，哪些工作可以共享？|换下一轮时，为什么不能直接沿用上一轮加满边的并查集？',
'先让两个查询的 mid 都等于 3，想想是否有必要把前三条边各加两遍。','本轮按时间只向前走；下一轮所需时间可能更早，必须回到干净起点。',
'用 4 个顶点、3 次加边、2 个查询，在纸上排两轮 mid 桶。只做流程模拟，暂不强求完整代码。','选学：并查集、离线处理、复杂度分析')
add('远征任务板：从会写到能迁移','用分层挑战验证能力，而不是用题量判定掌握。',
'''<p class="lead">每个任务都交四件东西：模型、理由、自己的代码、自测证据。</p><p>下面的原创任务可直接练习；外链用于正式读题、提交与约束核对。难度分层是本讲教学安排，不等同于官方比赛定级。</p>'''+table(['层级','任务与约束','输出 / 验收重点'],[['A · 边界稳定','有序整数数组，n≤10⁵；q≤10⁵ 次闭区间 [L,R] 数量查询，L≤R','每次输出数量；解释两种边界与缺失情况'],['B · 独立建模','切木条，n≤2×10⁵，1≤aᵢ≤10⁹，0≤K≤10⁹','输出最小整数长度上限；证明刀数公式'],['B · 官方迁移','<a href="https://atcoder.jp/contests/abc146/tasks/abc146_c" target="_blank" rel="noopener">ABC146 C · Buy an Integer</a>','价格含位数变化；处理一个也买不起与合法最大值'],['C · 贪心裁判','非负页数分书，n≤10⁵，aᵢ≤10⁹，1≤k≤n','输出至多 k 组时的最小最大组和；顺序与证明'],['C · 转换裁判','<a href="https://atcoder.jp/contests/abc023/tasks/abc023_d" target="_blank" rel="noopener">ABC023 D · 射撃王</a>','高度限制转截止时间，独立证明排序贪心'],['D · 图组合','第 18 站水位网格，行列各≤300，高度 0～10⁹，无永久障碍','输出最低可达水位；先过固定阈值 BFS'],['D · 代数组合','连续子段最大平均值，n≤10⁵，−10⁴≤aᵢ≤10⁴，1≤L≤n','输出近似值，绝对误差≤10⁻⁵；前缀范围与精度预算'],['D · 状态组合','<a href="https://atcoder.jp/contests/abc236/tasks/abc236_e" target="_blank" rel="noopener">ABC236 E · Average and Median</a>','先平均值，后中位数；阈值变换与受限选择 DP']])+'''<h3>怎样判断该不该升级？</h3><p>第一遍允许提示，留下提示级别。隔一天遮住讲义，自己读题、画小例、定义 check、写出单调证明，再实现。若换一个限制就说不清，先回到模型，不用增加同类题量。</p><p>基础 A、B 稳定后再进入 C。D 的图、前缀和、DP 可以按先修知识独立选路，不必一次全部攻完。一题可拆成“纸面建模”和“实现验证”两次短课。</p>''',
'你准备先挑战哪个任务，它对应你已经掌握的哪些工具？|如果把“至多”改成“恰好”，原来的 check 还成立吗？|隔天不看讲义，你最想重新证明哪一步？',
'先选能讲清主线、只有一个新难点的题。','练习目标不是第一次零提示，而是逐步减少依赖，并能迁移限制。',
'选一题，写下四格卡和三类自测计划。完成后记录实际提示，不预先把任何能力标成掌握。')
add('带走一张卡：从零到提高的共同方法','把二分变成可解释、可验证的解决问题过程。',
'''<p class="lead">二分的核心能力，是证明哪一片可能性可以放心排除。</p>'''+table(['写代码前','写完后'],[['我查的是位置、数值，还是请求前缀？','返回的是第一个真还是最后一个真？'],['check 的完整中文句子是什么？','check 是否每次重置工作状态？'],['为何单调，方向是哪一种？','每轮不变式成立、区间严格缩小吗？'],['内层裁判为何正确？','全真、全假、单元素、重复值怎样处理？'],['合法范围与端点依据是什么？','中间运算会溢出吗，实数误差够吗？'],['每轮成本、总轮数、额外空间？','能与暴力核对，并用新例子解释吗？']])+'''<h3>家长陪伴卡</h3><p>孩子卡住时，先让她手推一个固定阈值，听她解释“为什么不行”。一次只追问同一个根因的两三个关键问题。已经讲明白就让她修改或验证，不把每个符号都变成填空问答。</p><p>如果连续混乱或明显疲劳，当天只保存一张思路卡：题目要什么、哪些量会变、check 的一句话、一个手推例子、仍不确定的地方。隔天从题意重做，不强迫盯着乱代码硬修。</p><h3>反思由你完成</h3><p>改对或 AC 后，再自己说：我错在哪里？为什么会错？下次怎么防？还未完成的内容标为“待复盘”。教练可以补充判断，但不替你填写这三句话。</p><p>到提高阶段，二分循环通常不再是最难的部分。真正需要继续练的是：发现单调量，设计正确的判定，证明内层算法，并把复杂度压到限制以内。本讲提供这条路线；掌握需要独立作品与迁移证据。</p><p class="muted">关联阅读：<a href="../递归探险/递归探险指南.html">递归探险指南</a>。递归中的“任务定义与终止证明”，和二分中的“check 定义与收缩证明”，都在训练同一件事：说清每一步为何正确。</p>''',
'你能不用 mid、lo、hi 这些词解释二分吗？|这次最有帮助的反例是哪一个，它区分了哪两种想法？|下一次写二分前，你准备先写哪一句检查问题？',
'先从“我知道哪些候选一定不可能”开始讲。','检查动作必须能执行，例如“画出全假时的终止状态”，比“下次认真一点”更有用。',
'亲手写一张不超过半页的方法卡。只填自己实际做过、能解释的内容；其余保留为空白或待复盘。')
